// ================================================
// Nœud : Clean Email (Version Ultime Anti-Doublons)
// ================================================

const emailData = $('Email Trigger (IMAP)').isExecuted ? $('Email Trigger (IMAP)').first().json : $('Inject Test Email Data').first().json;
const currentItem = $input.item.json;

// 0. Réparer l'encodage Latin-1 mal interprété en UTF-8 (Ã© → é, Ã  → à, etc.)
function decodeLatin1AsUTF8(str) {
  if (!str) return "";
  str = str
    .replace(/Ã©/g, 'é').replace(/Ã¨/g, 'è').replace(/Ãª/g, 'ê').replace(/Ã«/g, 'ë')
    .replace(/Ã /g, 'à').replace(/Ã¢/g, 'â').replace(/Ã¤/g, 'ä')
    .replace(/Ã´/g, 'ô').replace(/Ã¶/g, 'ö').replace(/Ã»/g, 'û').replace(/Ã¹/g, 'ù').replace(/Ã¼/g, 'ü')
    .replace(/Ã®/g, 'î').replace(/Ã¯/g, 'ï')
    .replace(/Ã§/g, 'ç')
    .replace(/Å"/g, 'œ').replace(/Ã¦/g, 'æ')
    .replace(/Ã‰/g, 'É').replace(/Ã€/g, 'À').replace(/Ã‡/g, 'Ç').replace(/Ã"/g, 'Ô').replace(/Ã›/g, 'Û')
    .replace(/Ã‹/g, 'Ë').replace(/ÃŠ/g, 'Ê').replace(/Ã/g, 'Î')
    .replace(/â€™/g, "'").replace(/â€œ/g, '"').replace(/â€/g, '"')
    .replace(/â€"/g, '–').replace(/â€"/g, '—')
    .replace(/Â«/g, '«').replace(/Â»/g, '»')
    .replace(/Â /g, ' ')
    // ✅ NOUVEAU : supprimer les emojis corrompus (séquences â + caractères boîtes)
    .replace(/â[^\s\w,\.!?;:'"«»àâäéèêëîïôöùûüçœæÀÂÄÉÈÊËÎÏÔÖÙÛÜÇŒÆ-]{1,3}/g, '')
    // ✅ NOUVEAU : supprimer tous les caractères non-imprimables résiduels
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '')
    // ✅ NOUVEAU : nettoyer les espaces multiples laissés par les suppressions
    .replace(/  +/g, ' ');
  return str;
}

// 1. Récupérer le texte brut ou forcer la conversion du HTML
let rawText = emailData.textPlain || "";

if (!rawText || rawText.trim() === "") {
  let html = emailData.textHtml || "";
  html = html.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
  html = html.replace(/<!--[\s\S]*?-->/g, '');
  html = html.replace(/<br\s*\/?>/gi, '\n');
  html = html.replace(/<\/div>/gi, '\n');
  html = html.replace(/<\/p>/gi, '\n');
  html = html.replace(/&nbsp;/g, ' ')
             .replace(/&rsquo;/g, "'")
             .replace(/&#39;/g, "'")
             .replace(/&quot;/g, '"')
             .replace(/&lt;/g, '<')
             .replace(/&gt;/g, '>')
             .replace(/&eacute;/gi, 'é')
             .replace(/&agrave;/gi, 'à');
  html = html.replace(/<[^>]*>/g, '');
  rawText = html;
}

// Appliquer le décodage Latin-1 dès que possible
rawText = decodeLatin1AsUTF8(rawText);

// 2. Réparer les accents détruits par le serveur (\ufffd)
function repairBrokenFrench(str) {
  if (!str) return "";
  const char = '\ufffd';
  let repaired = str
    .replace(new RegExp('Envoy' + char, 'gi'), 'Envoyé')
    .replace(new RegExp('R' + char + 'p\\.', 'gi'), 'Rép.')
    .replace(new RegExp(' ' + char + ' ', 'g'), ' à ')
    .replace(new RegExp('\\n' + char + ' :', 'g'), '\nÀ :')
    .replace(new RegExp(char + 'poux', 'g'), 'époux')
    .replace(new RegExp('re' + char + 'u', 'g'), 'reçu')
    .replace(new RegExp('n\'' + char + 'tait', 'g'), 'n\'était')
    .replace(new RegExp('journ' + char + 'e', 'g'), 'journée')
    .replace(new RegExp('co' + char + 'te', 'g'), 'coûte')
    .replace(new RegExp(char + 'ducation', 'g'), 'éducation')
    .replace(new RegExp('d' + char + 'marre', 'g'), 'démarre')
    .replace(new RegExp('confirm' + char + 'e', 'g'), 'confirmée')
    .replace(new RegExp(char + 'ventuelles', 'g'), 'éventuelles')
    .replace(new RegExp(char + 'change', 'g'), 'échange')
    .replace(new RegExp('a ' + char + 'crit', 'g'), 'a écrit')
    .replace(new RegExp(char, 'g'), 'é');
  repaired = repaired.replace(/éé/g, 'é');
  return repaired;
}

let fixedText = repairBrokenFrench(rawText);

// 3. Extraire le dernier message
function extractLastMessage(text) {
  if (!text) return "";
  const normalizedText = text.replace(/\r\n/g, '\n');
  const patterns = [
    /\n\s*On\s+[\s\S]*?wrote\s*[:\s]/i,
    /\n\s*Le\s+[\s\S]*?a\s+écrit\s*[:\s]/i,
    /\n\s*De\s*[:\s].*\n?\s*Envoy.*[:\s]/i,
    /\n\s*From\s*[:\s].*\n?\s*Sent\s*[:\s]/i,
    /\n\s*---+\s*Mail original\s*---+/i,
    /\n\s*________________________________/i,
    /\n\s*>/
  ];
  let splitIndex = normalizedText.length;
  for (let i = 0; i < patterns.length; i++) {
    const match = normalizedText.match(patterns[i]);
    if (match && match.index < splitIndex) splitIndex = match.index;
  }
  let lastMessage = normalizedText.substring(0, splitIndex).trim();
  const mobileSigs = [
    /Envoy.* de Yahoo/i,
    /Envoy.* de mon iPhone/i,
    /Envoy.* de mon iPad/i,
    /Envoy.* de mon mobile/i,
    /Obtenir Outlook pour/i,
    // ✂️ Signature Educfinance — combinaisons précises uniquement
    /Djamel-Eddine\s+Bourouba/i,
    /Ambassadeur\s+Educfinance/i,
    /educfinance\.ca/i,
    /Chaleureusement,?\s*\n?\s*Djamel/i,  // "Chaleureusement, Djamel"
    /Cordialement,?\s*\n?\s*Djamel/i,
    /Au plaisir,?\s*\n?\s*Djamel/i,
  ];
  for (let j = 0; j < mobileSigs.length; j++) {
    const sigMatch = lastMessage.match(mobileSigs[j]);
    if (sigMatch) {
      lastMessage = lastMessage.substring(0, sigMatch.index).trim();
      break;
    }
  }
  return lastMessage;
}

const lastMessage = extractLastMessage(fixedText);

// 4. Préparer le HTML final pour Pipedrive
function escapeHTML(str) {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

const escapedMessage = escapeHTML(lastMessage);
const lastMessageHTML = `<div style="font-family: sans-serif; line-height: 1.5;">${escapedMessage.replace(/\n/g, '<br>')}</div>`;

return {
  ...currentItem,
  lastMessage: lastMessage,
  lastMessageHTML: lastMessageHTML
};

// ================================================
// Nœud : Clean Email (Branche INBOUND)
// ================================================

const emailData = $('Email Trigger (IMAP)').item.json;
const currentItem = $input.item.json.item || $input.item.json;

let rawText = emailData.textPlain || emailData.textHtml || "";

// -------------------------------------------------
// Étape 0 : Décoder Quoted-Printable (=C3=A9 → é, soft line breaks, etc.)
// Nécessaire quand l'email vient via IMAP batch (raw MIME non décodé)
// -------------------------------------------------
function decodeQuotedPrintable(str) {
  if (!str) return "";

  // Supprimer les MIME headers si présents (Content-Type:, Content-Transfer-Encoding:, etc.)
  // et ne garder que le corps
  const mimeHeaderEnd = str.indexOf("\n\n");
  if (mimeHeaderEnd !== -1 && str.includes("Content-Transfer-Encoding: quoted-printable")) {
    str = str.substring(mimeHeaderEnd + 2);
  }

  // 1. Rejoindre les soft line breaks (= en fin de ligne)
  str = str.replace(/=\r?\n/g, "");

  // 2. Décoder les séquences =XX en bytes, puis décoder en UTF-8
  const decoded = str.replace(/=([0-9A-Fa-f]{2})/g, (_, hex) => {
    return String.fromCharCode(parseInt(hex, 16));
  });

  // 3. Réinterpréter les bytes Latin-1 comme UTF-8
  try {
    const bytes = new Uint8Array(decoded.length);
    for (let i = 0; i < decoded.length; i++) {
      bytes[i] = decoded.charCodeAt(i) & 0xFF;
    }
    return new TextDecoder('utf-8').decode(bytes);
  } catch (e) {
    return decoded;
  }
}

// -------------------------------------------------
// Étape 1 : Détecter si le texte est en QP et décoder
// -------------------------------------------------
function isQuotedPrintable(str) {
  return /=[0-9A-Fa-f]{2}/.test(str) || /=\r?\n/.test(str);
}

if (isQuotedPrintable(rawText)) {
  rawText = decodeQuotedPrintable(rawText);
} else {
  // Sinon appliquer les corrections mojibake habituelles
  function decodeLatin1AsUTF8(str) {
    if (!str) return "";
    return str
      .replace(/Ã©/g, 'é').replace(/Ã¨/g, 'è').replace(/Ãª/g, 'ê').replace(/Ã«/g, 'ë')
      .replace(/Ã /g, 'à').replace(/Ã¢/g, 'â').replace(/Ã¤/g, 'ä')
      .replace(/Ã´/g, 'ô').replace(/Ã¶/g, 'ö').replace(/Ã»/g, 'û').replace(/Ã¹/g, 'ù').replace(/Ã¼/g, 'ü')
      .replace(/Ã®/g, 'î').replace(/Ã¯/g, 'ï')
      .replace(/Ã§/g, 'ç')
      .replace(/Å"/g, 'œ').replace(/Ã¦/g, 'æ')
      .replace(/Ã‰/g, 'É').replace(/Ã€/g, 'À').replace(/Ã‡/g, 'Ç').replace(/Ã"/g, 'Ô')
      .replace(/Ã‹/g, 'Ë').replace(/ÃŠ/g, 'Ê').replace(/Ã/g, 'Î')
      .replace(/â€™/g, "'").replace(/â€œ/g, '"').replace(/â€/g, '"')
      .replace(/â€"/g, '–').replace(/â€"/g, '—')
      .replace(/Â«/g, '«').replace(/Â»/g, '»')
      .replace(/Â /g, ' ');
  }
  rawText = decodeLatin1AsUTF8(rawText);
}

let fixedText = rawText;

// -------------------------------------------------
// Étape 2 : Supprimer les MIME boundaries et headers résiduels
// (--0000000000009fed58... Content-Type: text/plain...)
// -------------------------------------------------
function stripMimeBoundaries(str) {
  if (!str) return "";
  // Supprimer les lignes de boundary MIME (--xxxxx)
  str = str.replace(/^--[A-Za-z0-9_\-]+.*$/gm, "");
  // Supprimer les headers MIME résiduels
  str = str.replace(/^Content-Type:.*$/gm, "");
  str = str.replace(/^Content-Transfer-Encoding:.*$/gm, "");
  str = str.replace(/^MIME-Version:.*$/gm, "");
  str = str.replace(/^Content-Disposition:.*$/gm, "");
  // Nettoyer les lignes vides multiples
  str = str.replace(/\n{3,}/g, "\n\n");
  return str.trim();
}

fixedText = stripMimeBoundaries(fixedText);

// -------------------------------------------------
// Étape 3 : Extraire le dernier message (enlever les citations)
// -------------------------------------------------
function extractLastMessage(text) {
  if (!text) return "";

  const normalizedText = text.replace(/\r\n/g, '\n');

  const patterns = [
    /\n\s*Le\s+[\s\S]*?a\s+écrit\s*[:\s]/i,
    /\n\s*De\s*[:\s].*\n?\s*Envoy.*[:\s]/i,
    /\n\s*From\s*[:\s].*\n?\s*Sent\s*[:\s]/i,
    /\n\s*On\s+[\s\S]*?wrote\s*[:\s]/i,
    /\n\s*---+\s*Mail original\s*---+/i,
    /\n\s*________________________________/i,
    /\n\s*>/
  ];

  let splitIndex = normalizedText.length;
  for (let i = 0; i < patterns.length; i++) {
    const match = normalizedText.match(patterns[i]);
    if (match && match.index < splitIndex) {
      splitIndex = match.index;
    }
  }

  let lastMessage = normalizedText.substring(0, splitIndex).trim();

  const mobileSigs = [
    /Envoy.* de Yahoo/i,
    /Envoy.* de mon iPhone/i,
    /Envoy.* de mon iPad/i,
    /Envoy.* de mon mobile/i,
    /Obtenir Outlook pour/i,
  ];

  for (let j = 0; j < mobileSigs.length; j++) {
    const sigMatch = lastMessage.match(mobileSigs[j]);
    if (sigMatch) {
      lastMessage = lastMessage.substring(0, sigMatch.index).trim();
      break;
    }
  }

  return lastMessage;
}

const lastMessage = extractLastMessage(fixedText);

// -------------------------------------------------
// Étape 4 : Préparer le HTML
// -------------------------------------------------
function escapeHTML(str) {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

const escapedMessage = escapeHTML(lastMessage);
const lastMessageHTML = `<div style="font-family: sans-serif; line-height: 1.5;">${escapedMessage.replace(/\n/g, '<br>')}</div>`;

return {
  ...currentItem,
  lastMessage:     lastMessage,
  lastMessageHTML: lastMessageHTML
};

const { ImapFlow } = require('imapflow');

// Logger custom vide pour éviter le conflit pino/sandbox n8n
const silentLogger = {
  debug: () => {},
  info:  () => {},
  warn:  () => {},
  error: () => {},
  trace: () => {},
  child: () => silentLogger
};

const config = {
  host:   $env.IONOS_IMAP_HOST,
  port:   993,
  secure: true,
  auth: {
    user: $env.IONOS_USER,
    pass: $env.IONOS_PASS
  },
  logger: silentLogger
};

const client = new ImapFlow(config);
const emails = [];

try {
  await client.connect();
  const lock = await client.getMailboxLock('INBOX');

  try {
    const uids = await client.search({ seen: false });

    if (!uids || uids.length === 0) {
      return [{ json: { status: 'no_unseen_emails', count: 0 } }];
    }

    const toFetch = uids.slice(-50);

    for await (const msg of client.fetch(toFetch, {
      envelope:      true,
      bodyParts:     ['1', '2', 'TEXT'],
      bodyStructure: true,
      flags:         true
    })) {
      const fromAddr = msg.envelope.from?.[0];
      const toAddr   = msg.envelope.to?.[0];

      const from = fromAddr
        ? (fromAddr.name ? `${fromAddr.name} <${fromAddr.address}>` : fromAddr.address)
        : '';
      const to = toAddr
        ? (toAddr.name ? `${toAddr.name} <${toAddr.address}>` : toAddr.address)
        : '';

      let textPlain = '';
      let textHtml  = '';
      if (msg.bodyParts) {
        for (const [key, buf] of msg.bodyParts) {
          const text = buf.toString('utf-8');
          if (key === '1') textPlain = text;
          if (key === '2') textHtml  = text;
          if (key === 'TEXT' && !textPlain) textPlain = text;
        }
      }

      emails.push({
        json: {
          from,
          to,
          subject:   msg.envelope.subject   || '',
          date:      msg.envelope.date?.toISOString() || new Date().toISOString(),
          messageId: msg.envelope.messageId || '',
          textPlain,
          textHtml,
          metadata: {
            'message-id': msg.envelope.messageId || '',
            uid: msg.uid
          }
        }
      });
    }
  } finally {
    lock.release();
  }

  await client.logout();

} catch (error) {
  try { await client.logout(); } catch (_) {}
  throw new Error('Erreur IMAP: ' + error.message);
}

return emails;
